mapper.select:
SELECT a.*, d.name as doctor_name, dept.name as dept_name
FROM appointment a
LEFT JOIN doctor d ON a.doctor_id = d.id
LEFT JOIN department dept ON a.dept_id = dept.id
WHERE a.deleted = 0 AND d.deleted = 0 AND dept.deleted = 0

    AND (a.patient_name LIKE CONCAT('%', #{keyword}, '%') OR a.patient_phone LIKE CONCAT('%', #{keyword}, '%'))


    AND a.doctor_id = #{doctorId}


    AND a.dept_id = #{deptId}


    AND a.status = #{status}


    AND a.date >= #{startDate}


    AND a.date <= #{endDate}

ORDER BY a.create_time DESC
